#include <vector>

class Solution {
public:
    std::vector<std::vector<char>> simulateBombAndBoxes(std::vector<std::vector<char>>& grid) {
        int m = grid.size(), n = grid[0].size();
        for (int iter = 0; iter < m + n + 10; ++iter) {
            auto new_grid = grid;
            std::vector<std::pair<int, int>> exploding;
            int dr[] = {-1, 1, 0, 0};
            int dc[] = {0, 0, -1, 1};
            for (int r = 0; r < m; ++r) {
                for (int c = 0; c < n; ++c) {
                    if (grid[r][c] == '*') {
                        for (int d = 0; d < 4; ++d) {
                            int nr = r + dr[d], nc = c + dc[d];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == '#') {
                                exploding.push_back({r, c});
                                break;
                            }
                        }
                    }
                }
            }
            for (auto const& p : exploding) {
                for (int d1 = -1; d1 <= 1; ++d1) {
                    for (int d2 = -1; d2 <= 1; ++d2) {
                        int nr = p.first + d1, nc = p.second + d2;
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && new_grid[nr][nc] == '#') {
                            new_grid[nr][nc] = '-';
                        }
                    }
                }
            }
            grid = new_grid;
            std::vector<std::vector<bool>> is_static(m, std::vector<bool>(n, false));
            for (int r = 0; r < m; ++r) {
                for (int c = 0; c < n; ++c) {
                    if (grid[r][c] == '#') {
                        if (r == m - 1 || grid[r + 1][c] == '*') is_static[r][c] = true;
                    }
                }
            }
            bool changed = true;
            while (changed) {
                changed = false;
                for (int r = m - 2; r >= 0; --r) {
                    for (int c = 0; c < n; ++c) {
                        if (grid[r][c] == '#' && !is_static[r][c]) {
                            if (is_static[r + 1][c] && grid[r + 1][c] == '#') {
                                is_static[r][c] = true;
                                changed = true;
                            }
                        }
                    }
                }
            }
            auto next_grid = grid;
            bool moved = false;
            for (int r = m - 2; r >= 0; --r) {
                for (int c = 0; c < n; ++c) {
                    if (grid[r][c] == '#' && !is_static[r][c] && grid[r + 1][c] == '-') {
                        next_grid[r][c] = '-';
                        next_grid[r + 1][c] = '#';
                        moved = true;
                    }
                }
            }
            grid = next_grid;
            if (exploding.empty() && !moved) break;
        }
        return grid;
    }
};

import java.util.*;

class Solution {
    public char[][] simulateBombAndBoxes(char[][] grid) {
        int m = grid.length, n = grid[0].length;
        for (int iter = 0; iter < m + n + 10; iter++) {
            char[][] newGrid = new char[m][n];
            for (int r = 0; r < m; r++) newGrid[r] = Arrays.copyOf(grid[r], n);
            List<int[]> exploding = new ArrayList<>();
            int[] dr = {-1, 1, 0, 0};
            int[] dc = {0, 0, -1, 1};
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] == '*') {
                        for (int d = 0; d < 4; d++) {
                            int nr = r + dr[d], nc = c + dc[d];
                            if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] == '#') {
                                exploding.add(new int[]{r, c});
                                break;
                            }
                        }
                    }
                }
            }
            for (int[] p : exploding) {
                for (int d1 = -1; d1 <= 1; d1++) {
                    for (int d2 = -1; d2 <= 1; d2++) {
                        int nr = p[0] + d1, nc = p[1] + d2;
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && newGrid[nr][nc] == '#') {
                            newGrid[nr][nc] = '-';
                        }
                    }
                }
            }
            grid = newGrid;
            boolean[][] isStatic = new boolean[m][n];
            for (int r = 0; r < m; r++) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] == '#' && (r == m - 1 || grid[r + 1][c] == '*')) isStatic[r][c] = true;
                }
            }
            boolean changed = true;
            while (changed) {
                changed = false;
                for (int r = m - 2; r >= 0; r--) {
                    for (int c = 0; c < n; c++) {
                        if (grid[r][c] == '#' && !isStatic[r][c] && isStatic[r + 1][c] && grid[r + 1][c] == '#') {
                            isStatic[r][c] = true;
                            changed = true;
                        }
                    }
                }
            }
            char[][] nextGrid = new char[m][n];
            for (int r = 0; r < m; r++) nextGrid[r] = Arrays.copyOf(grid[r], n);
            boolean moved = false;
            for (int r = m - 2; r >= 0; r--) {
                for (int c = 0; c < n; c++) {
                    if (grid[r][c] == '#' && !isStatic[r][c] && grid[r + 1][c] == '-') {
                        nextGrid[r][c] = '-';
                        nextGrid[r + 1][c] = '#';
                        moved = true;
                    }
                }
            }
            grid = nextGrid;
            if (exploding.isEmpty() && !moved) break;
        }
        return grid;
    }
}

