    const m = grid.length, n = grid[0].length;
    for (let iter = 0; iter < m + n + 10; iter++) {
        let newGrid = grid.map(row => [...row]);
        const exploding = [];
        const dr = [-1, 1, 0, 0];
        const dc = [0, 0, -1, 1];
        for (let r = 0; r < m; r++) {
            for (let c = 0; c < n; c++) {
                if (grid[r][c] === '*') {
                    for (let d = 0; d < 4; d++) {
                        const nr = r + dr[d], nc = c + dc[d];
                        if (nr >= 0 && nr < m && nc >= 0 && nc < n && grid[nr][nc] === '#') {
                            exploding.push([r, c]);
                            break;
                        }
                    }
                }
            }
        }
        for (const [br, bc] of exploding) {
            for (let d1 = -1; d1 <= 1; d1++) {
                for (let d2 = -1; d2 <= 1; d2++) {
                    const nr = br + d1, nc = bc + d2;
                    if (nr >= 0 && nr < m && nc >= 0 && nc < n && newGrid[nr][nc] === '#') {
                        newGrid[nr][nc] = '-';
                    }
                }
            }
        }
        grid = newGrid;
        const isStatic = Array.from({ length: m }, () => new Array(n).fill(false));
        for (let r = 0; r < m; r++) {
            for (let c = 0; c < n; c++) {
                if (grid[r][c] === '#' && (r === m - 1 || grid[r + 1][c] === '*')) isStatic[r][c] = true;
            }
        }
        let changed = true;
        while (changed) {
            changed = false;
            for (let r = m - 2; r >= 0; r--) {
                for (let c = 0; c < n; c++) {
                    if (grid[r][c] === '#' && !isStatic[r][c] && isStatic[r + 1][c] && grid[r + 1][c] === '#') {
                        isStatic[r][c] = true;
                        changed = true;
                    }
                }
            }
        }
        const nextGrid = grid.map(row => [...row]);
        let moved = false;
        for (let r = m - 2; r >= 0; r--) {
            for (let c = 0; c < n; c++) {
                if (grid[r][c] === '#' && !isStatic[r][c] && grid[r + 1][c] === '-') {
                    nextGrid[r][c] = '-';
                    nextGrid[r + 1][c] = '#';
                    moved = true;
                }
            }
        }
        grid = nextGrid;
        if (exploding.length === 0 && !moved) break;
